/* 组件就绪后执行 */
Eam.registerInit(async function(){
(()=>{
 const list=document.getElementById('history-list');if(!list)return;const s=Eam.s;
 const pages={report:'defect',check:'inspection',order:'order',execution:'order',acceptance:'acceptance',task:'inspection',result:'inspection',standard:'standards',plan:'plans',equipment:'equipment',restriction:'device',part:'equipment',attachment:'equipment',reportDraft:'defect'};
 function detail(e){const container=document.getElementById('source-detail');container.replaceChildren();Eam.row(container,e.objectType+' / '+e.objectId,'对象版本 '+e.version+' / 操作者 '+e.actor+' / 事件与接收 '+e.time+' / '+e.receivedAt);if(Eam.can(['auditor','admin','engineer'])||['standard','plan'].includes(e.objectType)){const details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent='展开审计字段快照';pre.textContent=JSON.stringify(e.details,null,2);details.append(summary,pre);container.append(details);}const versionEvent=['standard','plan'].includes(e.objectType);const draftEvent=versionEvent&&(e.details.status==='draft'||e.details.draft||e.details.removedDraft);const b=document.createElement('button');b.textContent=draftEvent?'草稿变更请查看审计快照':'打开关联业务';b.disabled=!!draftEvent;b.onclick=()=>{const p=pages[e.objectType]||'history';const query={};if(versionEvent)query.revision=e.details.current?.revision??e.details.revision??e.objectId;if(['part','attachment'].includes(e.objectType))query.structure=e.details.equipmentId||e.details.record?.equipmentId||'EQ-001';if(e.objectType==='report')query.report=e.objectId;if(e.objectType==='check'){query.tab='special';query.check=e.objectId;}if(['order','execution','acceptance'].includes(e.objectType))query.order=e.details.orderId||e.objectId;if(e.objectType==='task')query.task=e.objectId;if(e.objectType==='result')query.task=e.details.taskId;Eam.go(p,query);};container.append(b);}
 function render(){list.replaceChildren();const type=Eam.value('history-type'),date=Eam.value('history-date');const equipmentId=new URLSearchParams(location.search).get('equipment')||'EQ-001';const events=s.events.filter(e=>EamProduct.eventEquipment(e)===equipmentId&&(!type||e.objectType===type)&&(!date||e.time.slice(0,10)===date));const record=s.equipmentRecords.find(x=>x.id===equipmentId);if(record?.commissionedAt&&(!type||type==='equipment')&&(!date||date===record.commissionedAt)){const baseline=document.createElement('div');baseline.className='event';const title=document.createElement('b');title.textContent='投用日期（台账登记） / '+record.commissionedAt;const note=document.createElement('p');note.textContent='来源：设备台账日期字段；验收原始凭证未接入，不等同审批证据';baseline.append(title,note);list.append(baseline);}for(const e of events){const el=document.createElement('div');el.className='event';const b=document.createElement('button');b.className='text-button';b.textContent=e.text;b.onclick=()=>detail(e);const p=document.createElement('p');p.className='muted';p.textContent=e.actor+' / '+e.actorId+' / '+e.time+' / '+e.objectType+':'+e.objectId;el.append(b,p);list.append(el);}if(!events.length){const p=document.createElement('p');p.textContent='当前筛选无事件；初始投用信息见设备概览。';list.append(p);}}
 document.getElementById('history-type').onchange=render;document.getElementById('history-date').onchange=render;render();
 const event=s.events.find(e=>e.id===new URLSearchParams(location.search).get('source')&&EamProduct.eventEquipment(e)===(new URLSearchParams(location.search).get('equipment')||'EQ-001'));if(event)detail(event);
})();

});
